      bps: fc.integer({ min: 0, max: RATE_MAX_BPS }),
      years: fc.integer({ min: 1, max: 40 }),
    }),
  },
)

function twoDp(units: number): string {
  const whole = Math.floor(units / 100)
  const frac = String(units % 100).padStart(2, '0')
  return `${whole}.${frac}`
}

function amountText(c: Case | { cents: number }): string {
  return twoDp(c.cents)
}

function rateText(c: { bps: number }): string {
  return twoDp(c.bps)
}

function describeCase(c: Case): string {
  return `amount=${amountText(c)} rate=${rateText(c)} months=${c.months} asYears=${c.asYears}`
}

/** Per-file cache: identical seeds produce identical cases, so each loan is computed once. */
const cache = new Map<string, CalculatedLoan>()

function loanFor(c: Case): CalculatedLoan {
  const useYears = c.asYears && c.months % 12 === 0
  const unit: Unit = useYears ? 'years' : 'months'
  const key = `${c.cents}|${c.bps}|${unit}|${useYears ? c.months / 12 : c.months}`
  const cached = cache.get(key)
  if (cached) return cached
  const result = validateInputs({
    amount: amountText(c),
    rate: rateText(c),
    tenure: String(useYears ? c.months / 12 : c.months),
    unit,
  })
  if (!result.ok) {
    throw new Error(`generator produced invalid input: ${describeCase(c)} ${JSON.stringify(result.errors)}`)
  }
  const loan = calculateLoan(result.value)
  cache.set(key, loan)
  return loan
}

const HALF_UP = Decimal.ROUND_HALF_UP
const CENT = new Decimal('0.01')
const rate = (c: Case) => new Decimal(rateText(c))
const principalAmount = (c: Case) => new Decimal(amountText(c))

function sum(values: InstanceType<typeof Decimal>[]) {
  return values.reduce((acc, v) => acc.plus(v), new Decimal(0))
}

// Each checker throws a descriptive error on the first violation.
function checkRowCount(c: Case): void {
  const loan = loanFor(c)
  expect(loan.rows.length, describeCase(c)).toBe(c.months)
  expect(loan.rows.map((r) => r.month), describeCase(c)).toEqual(
    Array.from({ length: c.months }, (_, i) => i + 1),
  )
}

function checkPaymentSplit(c: Case): void {
  const loan = loanFor(c)
  let opening = principalAmount(c)
  loan.rows.forEach((r) => {
    expect(r.payment.eq(r.interest.plus(r.principal)), `${describeCase(c)} month ${r.month}: payment = interest + principal`).toBe(true)
    const expectedInterest = opening.mul(rate(c)).div(1200).toDecimalPlaces(2, HALF_UP)
    expect(
      r.interest.eq(expectedInterest),
      `${describeCase(c)} month ${r.month}: interest ${r.interest.toFixed(2)} vs ${expectedInterest.toFixed(2)}`,
    ).toBe(true)
    opening = r.balance
  })
}

function checkBalanceChain(c: Case): void {
  const loan = loanFor(c)
  let opening = principalAmount(c)
  loan.rows.forEach((r) => {
    expect(r.principal.gte(0), `${describeCase(c)} month ${r.month}: principal >= 0`).toBe(true)
    expect(r.principal.lte(opening), `${describeCase(c)} month ${r.month}: principal <= opening`).toBe(true)
    expect(r.balance.gte(0), `${describeCase(c)} month ${r.month}: balance >= 0`).toBe(true)
    expect(
      r.balance.eq(opening.minus(r.principal)),
      `${describeCase(c)} month ${r.month}: balance = previous balance - principal`,
    ).toBe(true)
    expect(r.payment.decimalPlaces(), `${describeCase(c)} month ${r.month}: payment dp`).toBeLessThanOrEqual(2)
    expect(r.interest.decimalPlaces()).toBeLessThanOrEqual(2)
    expect(r.principal.decimalPlaces()).toBeLessThanOrEqual(2)
    expect(r.balance.decimalPlaces()).toBeLessThanOrEqual(2)
    opening = r.balance
  })
}

function checkFinalBalance(c: Case): void {
  const loan = loanFor(c)
  const last = loan.rows[loan.rows.length - 1]
  expect(last.balance.isZero(), `${describeCase(c)}: final balance ${last.balance.toFixed(2)}`).toBe(true)
  expect(sum(loan.rows.map((r) => r.principal)).eq(principalAmount(c)), `${describeCase(c)}: sum of principal = P`).toBe(true)
}

function checkPaymentsNearHeadline(c: Case): void {
  const loan = loanFor(c)
  const first = loan.rows[0].payment
  expect(loan.monthlyPayment.eq(first), `${describeCase(c)}: headline = payment_1`).toBe(true)
  loan.rows.forEach((r) => {
    expect(
      r.payment.minus(first).abs().lte(CENT),
      `${describeCase(c)} month ${r.month}: payment ${r.payment.toFixed(2)} vs headline ${first.toFixed(2)}`,
    ).toBe(true)
  })
  const differs = loan.rows.some((r) => !r.payment.eq(first))
  expect(loan.showRoundingNote, `${describeCase(c)}: showRoundingNote`).toBe(differs)
