function checkTotals(c: Case): void {
  const loan = loanFor(c)
  const totalInterest = sum(loan.rows.map((r) => r.interest))
  const totalPayable = sum(loan.rows.map((r) => r.payment))
  expect(loan.totalInterest.eq(totalInterest), `${describeCase(c)}: total interest = sum of Interest column`).toBe(true)
  expect(loan.totalPayable.eq(totalPayable), `${describeCase(c)}: total payable = sum of Payment column`).toBe(true)
  expect(
    loan.totalPayable.eq(principalAmount(c).plus(loan.totalInterest)),
    `${describeCase(c)}: total payable = P + total interest`,
  ).toBe(true)
}

function checkYearsEqualMonths(y: { cents: number; bps: number; years: number }): void {
  const base = { cents: y.cents, bps: y.bps }
  const asYears = loanFor({ ...base, months: y.years * 12, asYears: true })
  const asMonths = loanFor({ ...base, months: y.years * 12, asYears: false })
  const label = `amount=${twoDp(y.cents)} rate=${twoDp(y.bps)} years=${y.years}`
  expect(asYears.input.unit, label).toBe('years')
  expect(asMonths.input.unit, label).toBe('months')
  expect(asYears.rows.length, label).toBe(asMonths.rows.length)
  asYears.rows.forEach((r, i) => {
    const m = asMonths.rows[i]
    expect(r.month, label).toBe(m.month)
    expect(r.payment.eq(m.payment), `${label} month ${r.month} payment`).toBe(true)
    expect(r.interest.eq(m.interest), `${label} month ${r.month} interest`).toBe(true)
    expect(r.principal.eq(m.principal), `${label} month ${r.month} principal`).toBe(true)
    expect(r.balance.eq(m.balance), `${label} month ${r.month} balance`).toBe(true)
  })
  expect(asYears.monthlyPayment.eq(asMonths.monthlyPayment), label).toBe(true)
  expect(asYears.totalInterest.eq(asMonths.totalInterest), label).toBe(true)
  expect(asYears.totalPayable.eq(asMonths.totalPayable), label).toBe(true)
  expect(asYears.showRoundingNote, label).toBe(asMonths.showRoundingNote)
}

