        checkBalanceChain(c)
        checkFinalBalance(c)
        checkPaymentsNearHeadline(c)
        checkTotals(c)
      }
    },
    TIMEOUT,
  )

  it(
    '[AC-3.6][AC-10.4][AC-10.5][AC-13.3][SPEC-§5.4] every reference loan (and both SPEC-§5.3 regressions) satisfies invariants 1 to 7',
    () => {
      for (const c of references) {
